"""A small, dependency-free reader for the configuration's TOML data types.

The configuration format uses ordered tables, arrays and scalar values.  This
reader also accepts the historical duplicate-key behavior (the last value wins
without moving the key in its table).
"""
import re


class InvalidToml(ValueError):
    pass


class Reader:
    def __init__(self, text):
        self.text = text.replace('\r\n', '\n')
        self.pos = 0
        self.explicit_tables = set()

    def fail(self):
        raise InvalidToml('invalid configuration')

    def peek(self, n=1):
        return self.text[self.pos:self.pos+n]

    def skip(self, newlines=False):
        spaces = ' \t\n' if newlines else ' \t'
        while self.pos < len(self.text):
            if self.peek() in spaces:
                self.pos += 1
            elif self.peek() == '#':
                while self.pos < len(self.text) and self.peek() != '\n':
                    self.pos += 1
                if not newlines:
                    return
            else:
                return

    def take(self, text):
        if not self.text.startswith(text, self.pos):
            self.fail()
        self.pos += len(text)

    def string(self):
        quote = self.peek()
        self.take(quote)
        multi = self.peek(2) == quote * 2
        if multi:
            self.pos += 2
            if self.peek() == '\n':
                self.pos += 1
        result = []
        while self.pos < len(self.text):
            if self.peek(3 if multi else 1) == quote * (3 if multi else 1):
                self.pos += 3 if multi else 1
                return ''.join(result)
            ch = self.peek()
            self.pos += 1
            if ch == '\n' and not multi:
                self.fail()
            if ord(ch) < 32 and ch not in '\t\n':
                self.fail()
            if ch == '\\' and quote == '"':
                esc = self.peek()
                self.pos += 1
                escapes = {'b': '\b', 't': '\t', 'n': '\n', 'f': '\f', 'r': '\r', '"': '"', '\\': '\\'}
                if esc in escapes:
                    result.append(escapes[esc])
                elif esc in ('u', 'U'):
                    n = 4 if esc == 'u' else 8
                    digits = self.peek(n)
                    if not re.fullmatch('[0-9a-fA-F]{%d}' % n, digits):
                        self.fail()
                    self.pos += n
                    try:
                        c = chr(int(digits, 16))
                        if 0xd800 <= ord(c) <= 0xdfff:
                            self.fail()
                        result.append(c)
                    except ValueError:
                        self.fail()
                elif multi and esc in ' \t\n':
                    while self.pos < len(self.text) and self.peek() in ' \t\n':
                        self.pos += 1
                else:
                    self.fail()
            else:
                result.append(ch)
        self.fail()

    def key(self):
        self.skip()
        keys = []
        while True:
            if self.peek() in ('"', "'"):
                keys.append(self.string())
            else:
                m = re.match(r'[A-Za-z0-9_-]+', self.text[self.pos:])
                if not m:
                    self.fail()
                keys.append(m[0])
                self.pos += len(m[0])
            self.skip()
            if self.peek() != '.':
                return keys
            self.pos += 1
            self.skip()

    def value(self):
        self.skip()
        ch = self.peek()
        if ch in ('"', "'"):
            return self.string()
        if ch == '[':
            self.pos += 1
            out = []
            self.skip(True)
            if self.peek() == ']':
                self.pos += 1
                return out
            while True:
                out.append(self.value())
                self.skip(True)
                if self.peek() == ']':
                    self.pos += 1
                    return out
                self.take(',')
                self.skip(True)
                if self.peek() == ']':
                    self.pos += 1
                    return out
        if ch == '{':
            self.pos += 1
            out = {}
            self.skip()
            if self.peek() == '}':
                self.pos += 1
                return out
            while True:
                keys = self.key()
                self.take('=')
                self.assign(out, keys, self.value())
                self.skip()
                if self.peek() == '}':
                    self.pos += 1
                    return out
                self.take(',')
                self.skip()
        start = self.pos
        while self.pos < len(self.text) and self.peek() not in ' \t\n,]}#':
            self.pos += 1
        word = self.text[start:self.pos]
        if word == 'true':
            return True
        if word == 'false':
            return False
        if re.fullmatch(r'[+-]?(?:0|[1-9][0-9_]*|0[xob][0-9a-fA-F_]+)', word):
            try:
                return int(word.replace('_',''), 0 if '0x' in word or '0o' in word or '0b' in word else 10)
            except ValueError:
                self.fail()
        if re.fullmatch(r'[+-]?(?:[0-9][0-9_]*\.[0-9_]+(?:[eE][+-]?[0-9_]+)?|[0-9][0-9_]*[eE][+-]?[0-9_]+|inf|nan)', word):
            try:
                return float(word.replace('_', ''))
            except ValueError:
                self.fail()
        if re.fullmatch(r'\d{4}-\d\d-\d\d(?:[Tt]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?)?', word):
            # A distinct non-string scalar is sufficient: no configuration field
            # consumes dates, but they may occur in unrelated tables.
            return ('datetime', word)
        self.fail()

    def assign(self, table, keys, value):
        for k in keys[:-1]:
            if k not in table:
                table[k] = {}
            table = table[k]
            if not isinstance(table, dict):
                self.fail()
        table[keys[-1]] = value

    def finish_line(self):
        self.skip()
        if self.pos < len(self.text):
            self.take('\n')

    def read(self):
        root = {}
        current = root
        while True:
            self.skip(True)
            if self.pos == len(self.text):
                return root
            if self.peek() == '[':
                self.pos += 1
                array = self.peek() == '['
                if array:
                    self.pos += 1
                keys = self.key()
                self.take(']]' if array else ']')
                keytuple = tuple(keys)
                if not array and keytuple in self.explicit_tables:
                    self.fail()
                self.explicit_tables.add(keytuple)
                current = root
                for k in keys[:-1]:
                    if k not in current:
                        current[k] = {}
                    current = current[k]
                    if isinstance(current, list):
                        current = current[-1]
                    if not isinstance(current, dict):
                        self.fail()
                k = keys[-1]
                if array:
                    if k not in current:
                        current[k] = []
                    if not isinstance(current[k], list):
                        self.fail()
                    current[k].append({})
                    current = current[k][-1]
                else:
                    if k not in current:
                        current[k] = {}
                    current = current[k]
                    if not isinstance(current, dict):
                        self.fail()
                self.finish_line()
            else:
                keys = self.key()
                self.take('=')
                self.assign(current, keys, self.value())
                self.finish_line()


def loads(text):
    return Reader(text).read()
PY"}

