"""Read a Git history and format a conventionally grouped changelog."""
from collections import OrderedDict
from dataclasses import dataclass
from datetime import datetime, timezone
import os
import re
import subprocess
import sys
import unicodedata

import toml_reader


class Failure(Exception):
    pass


IO_ERROR = 'fatal I/O error with output file'
TOML_ERROR = 'Failed to parse TOML configuration file'
VERSION_ERROR = 'Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format.'


def read_config(path):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            text = f.read()
    except (OSError, ValueError, UnicodeError):
        raise Failure(IO_ERROR)
    try:
        config = toml_reader.loads(text)
        clog = config['clog']
        if not isinstance(clog, dict):
            raise ValueError()
        string_fields = ('repository', 'subtitle', 'git-dir', 'outfile', 'infile', 'changelog', 'link-style', 'output-format')
        for key in string_fields:
            if key in clog and not isinstance(clog[key], str):
                raise ValueError()
        if 'from-latest-tag' in clog and not isinstance(clog['from-latest-tag'], bool):
            raise ValueError()
        if 'link-style' in clog and clog['link-style'].lower() not in ('github', 'gitlab', 'stash', 'cgit'):
            raise ValueError()
        if 'output-format' in clog and clog['output-format'].lower() not in ('markdown', 'json'):
            raise ValueError()
        sections = config.get('sections', {})
        if not isinstance(sections, dict):
            raise ValueError()
        for title, aliases in sections.items():
            if not isinstance(aliases, list) or any(not isinstance(x, str) for x in aliases):
                raise ValueError()
        return clog, sections
    except (KeyError, ValueError, TypeError, IndexError, RecursionError):
        raise Failure(TOML_ERROR)


class History:
    def __init__(self, git_dir, work_tree):
        self.prefix = ['git', '--git-dir=' + git_dir, '--work-tree=' + work_tree]
        self.valid = os.path.isdir(git_dir)

    def run(self, *args):
        try:
            result = subprocess.run(self.prefix + list(args), stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
            if result.returncode:
                return ''
            return result.stdout.decode('utf-8', errors='replace')
        except OSError:
            return ''

    def latest_tag(self):
        return self.run('describe', '--tags', '--abbrev=0').strip()

    def log(self, from_commit, to_commit):
        args = ['log', '--format=%H%x00%s%x00%b%x00']
        if from_commit is not None:
            args.append(from_commit + '..' + to_commit)
        text = self.run(*args)
        fields = text.split('\0')
        for i in range(0, len(fields)-2, 3):
            commit_hash, subject, body = fields[i:i+3]
            commit_hash = commit_hash.strip()
            if re.fullmatch(r'[0-9a-f]{40,64}', commit_hash):
                yield commit_hash, subject, body


SUBJECT = re.compile(r'^([^:(]+)(?:\(([^)]*)\))?:(.*)$')
CLOSES = re.compile(r'(?:Closes|Fixes|Resolves)\s#(\d+)(?:,\s#(\d+))*')
BREAKS = re.compile(r'Breaks\s#(\d+)(?:,\s#(\d+))*|(?i:breaking)')


def references(pattern, body):
    return [m[2] if m[2] is not None else (m[1] or '') for m in pattern.finditer(body)]


@dataclass
class Commit:
    hash: str
    component: str
    subject: str
    closes: list
    breaks: list


class Links:
    def __init__(self, repository, style):
        self.repository = repository
        self.style = style

    def commit(self, commit):
        if self.repository is None:
            return commit.hash[:8]
        fragment = {'github': '/commit/', 'gitlab': '/commit/', 'stash': '/commits/', 'cgit': '/commit/?id='}[self.style]
        return self.repository + fragment + commit.hash

    def issue(self, issue):
        if self.repository is None or self.style in ('stash', 'cgit'):
            return issue
        return self.repository + '/issues/' + issue


def group_commits(history, sections, from_commit, to_commit):
    alias_section = {}
    for title, aliases in sections.items():
        for alias in aliases:
            alias_section.setdefault(alias, title)
    groups = OrderedDict((title, {}) for title in sections)
    for hash_, subject, body in history.log(from_commit, to_commit):
        match = SUBJECT.match(subject)
        if not match:
            continue
        type_, component, subject = match.groups()
        if type_ not in alias_section:
            continue
        component = component or ''
        commit = Commit(hash_, component, subject, references(CLOSES, body), references(BREAKS, body))
        title = alias_section[type_]
        groups[title].setdefault(component, []).append(commit)
    return [(title, [(component, comps[component]) for component in sorted(comps)]) for title, comps in groups.items() if comps]


def rust_string(value):
    """Quote string fields, retaining Unicode and the observed debug escapes."""
    result = ['"']
    escapes = {'"': '\\"', '\\': '\\\\', '\n': '\\n', '\r': '\\r', '\t': '\\t', '\0': '\\0'}
    for char in value:
        if char in escapes:
            result.append(escapes[char])
        elif unicodedata.category(char) in ('Cc', 'Cf', 'Cs', 'Co', 'Cn') or (char.isspace() and char not in ' '):
            result.append('\\u{%x}' % ord(char))
        else:
            result.append(char)
    result.append('"')
    return ''.join(result)


def markdown(version, subtitle, date, groups, links):
    out = '<a name="' + (version or '') + '"></a>\n## ' + (version or '') + ' ' + (subtitle or '') + ' (' + date + ')\n\n'
    for title, components in groups:
